typedef struct {
    double x, y;
} Point;

static int cmp_points(const void *a, const void *b) {
    const Point *p = (const Point *)a;
    const Point *q = (const Point *)b;
    if (p->x < q->x) return -1;
    if (p->x > q->x) return 1;
    if (p->y < q->y) return -1;
    if (p->y > q->y) return 1;
    return 0;
}

static double dist(Point a, Point b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return sqrt(dx * dx + dy * dy);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    if (n <= 0) {
        printf("0.0000000000\n");
        return 0;
    }

    Point *p = (Point *)malloc((size_t)n * sizeof(Point));
    for (int i = 0; i < n; ++i) {
        scanf("%lf %lf", &p[i].x, &p[i].y);
    }

    qsort(p, n, sizeof(Point), cmp_points);

    if (n == 1) {
        printf("0.0000000000\n");
        free(p);
        return 0;
    }

    double **dp = (double **)malloc((size_t)n * sizeof(double *));
    for (int i = 0; i < n; ++i) {
        dp[i] = (double *)malloc((size_t)n * sizeof(double));
        for (int j = 0; j < n; ++j) dp[i][j] = 1e100;
    }

    dp[0][1] = dist(p[0], p[1]);

    for (int j = 2; j < n; ++j) {
        for (int i = 0; i < j - 1; ++i) {
            dp[i][j] = dp[i][j - 1] + dist(p[j - 1], p[j]);
        }

        double best = 1e100;
        for (int k = 0; k < j - 1; ++k) {
            double cand = dp[k][j - 1] + dist(p[k], p[j]);
            if (cand < best) best = cand;
        }
        dp[j - 1][j] = best;
    }

    double ans = dp[n - 2][n - 1] + dist(p[n - 2], p[n - 1]);

    printf("%.10f\n", ans);

    for (int i = 0; i < n; ++i) free(dp[i]);
    free(dp);
    free(p);
    return 0;
}

