int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<Point> p(n);
    for (int i = 0; i < n; i++) {
        cin >> p[i].x >> p[i].y;
    }
    // Sort by x coordinate (left to right)
    sort(p.begin(), p.end(), [](const Point& a, const Point& b) {
        return a.x < b.x;
    });

    // dp[i][j] = shortest path where one path ends at i, the other at j (i > j)
    vector<vector<double>> dp(n, vector<double>(n, 1e30));
    dp[0][0] = 0.0;
    // The two paths start from point 0 together
    dp[1][0] = dist(p[0], p[1]);

    for (int i = 2; i < n; i++) {
        // case 1: j < i-1, the new point i extends the path that ended at i-1
        for (int j = 0; j < i - 1; j++) {
            dp[i][j] = min(dp[i][j], dp[i-1][j] + dist(p[i-1], p[i]));
            dp[j][i] = dp[i][j]; // symmetry
        }
        // case 2: j = i-1, the new point i connects to some earlier point k
        for (int k = 0; k < i - 1; k++) {
            dp[i][i-1] = min(dp[i][i-1], dp[i-1][k] + dist(p[k], p[i]));
            dp[i-1][i] = dp[i][i-1];
        }
    }

    // Final answer: one path ends at n-1, the other at some j, then connect j to n-1
    double ans = 1e30;
    for (int j = 0; j < n - 1; j++) {
        ans = min(ans, dp[n-1][j] + dist(p[j], p[n-1]));
    }
    cout << fixed << setprecision(2) << ans << "\n";

    return 0;
}

