public class BitonicTSP {
    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
        double distTo(Point other) {
            double dx = this.x - other.x;
            double dy = this.y - other.y;
            return Math.sqrt(dx * dx + dy * dy);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        Point[] points = new Point[n];
        for (int i = 0; i < n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            double x = Double.parseDouble(st.nextToken());
            double y = Double.parseDouble(st.nextToken());
            points[i] = new Point(x, y);
        }

        // Sort by x-coordinate
        Arrays.sort(points, (a, b) -> Double.compare(a.x, b.x));

        // dp[i][j] for i > j: shortest path covering points 0..i,
        // one path ends at i, the other at j.
        double[][] dp = new double[n][n];
        for (double[] row : dp) Arrays.fill(row, Double.MAX_VALUE / 2);
        dp[1][0] = points[0].distTo(points[1]);

        for (int i = 2; i < n; i++) {
            // Case: j < i-1
            for (int j = 0; j < i - 1; j++) {
                dp[i][j] = dp[i - 1][j] + points[i - 1].distTo(points[i]);
            }
            // Case: j = i-1
            dp[i][i - 1] = Double.MAX_VALUE / 2;
            for (int k = 0; k < i - 1; k++) {
                double candidate = dp[i - 1][k] + points[k].distTo(points[i]);
                if (candidate < dp[i][i - 1]) {
                    dp[i][i - 1] = candidate;
                }
            }
        }

        double answer = dp[n - 1][n - 2] + points[n - 2].distTo(points[n - 1]);
        System.out.printf("%.2f%n", answer);
    }
}

