/*
Bitonic TSP
-----------
Given N points in the plane, find the shortest bitonic tour:
start at the leftmost point, move monotonically to the rightmost point,
then return monotonically back to the start, visiting every point.

Classic DP:
Let points be sorted by x-coordinate: p[0..n-1].

dp[i][j] for i < j:
  shortest total length of two disjoint monotone paths starting at p[0]
  and ending at p[i] and p[j], having visited points 0..j exactly once.

Transition:
- If i < j-1:
    dp[i][j] = dp[i][j-1] + dist(j-1, j)
- If i == j-1:
    dp[j-1][j] = min over k < j-1 of dp[k][j-1] + dist(k, j)

Base:
  dp[0][1] = dist(0, 1)

Answer:
  dp[n-2][n-1] + dist(n-2, n-1)

Time: O(N^2)
Memory: O(N^2)
*/

public class Main {
    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
    }

    static double dist(Point a, Point b) {
        double dx = a.x - b.x;
        double dy = a.y - b.y;
        return Math.hypot(dx, dy);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        Point[] p = new Point[n];
        for (int i = 0; i < n; i++) {
            double x = fs.nextDouble();
            double y = fs.nextDouble();
            p[i] = new Point(x, y);
        }

        Arrays.sort(p, (a, b) -> {
            if (a.x != b.x) return Double.compare(a.x, b.x);
            return Double.compare(a.y, b.y);
        });

        if (n == 1) {
            System.out.printf(Locale.US, "%.10f%n", 0.0);
            return;
        }
        if (n == 2) {
            System.out.printf(Locale.US, "%.10f%n", 2.0 * dist(p[0], p[1]));
            return;
        }

        double[][] dp = new double[n][n];
        for (int i = 0; i < n; i++) Arrays.fill(dp[i], Double.POSITIVE_INFINITY);

        dp[0][1] = dist(p[0], p[1]);

        for (int j = 2; j < n; j++) {
            for (int i = 0; i < j - 1; i++) {
                dp[i][j] = dp[i][j - 1] + dist(p[j - 1], p[j]);
            }

            for (int k = 0; k < j - 1; k++) {
                dp[j - 1][j] = Math.min(dp[j - 1][j], dp[k][j - 1] + dist(p[k], p[j]));
            }
        }

        double ans = dp[n - 2][n - 1] + dist(p[n - 2], p[n - 1]);
        System.out.printf(Locale.US, "%.10f%n", ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import sys
from math import sqrt

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    results = []
    while idx < len(input_data):
        n = int(input_data[idx]); idx += 1
        if n == 0:
            break
        points = []
        for i in range(n):
            x = float(input_data[idx]); y = float(input_data[idx+1]); idx += 2
            points.append((x, y))
        points.sort()

        def dist(i, j):
            dx = points[i][0] - points[j][0]
            dy = points[i][1] - points[j][1]
            return sqrt(dx*dx + dy*dy)

        INF = float('inf')
        # dp[i][j] i > j
        dp = [[INF]*n for _ in range(n)]
        dp[1][0] = dist(0, 1)

        for i in range(1, n-1):
            # extend path at i to i+1
            for j in range(i):
                if dp[i][j] < INF:
                    val = dp[i][j] + dist(i, i+1)
                    if val < dp[i+1][j]:
                        dp[i+1][j] = val
            # extend path at j to i+1 (new state: dp[i+1][i])
            for j in range(i):
                if dp[i][j] < INF:
                    val = dp[i][j] + dist(j, i+1)
                    if val < dp[i+1][i]:
                        dp[i+1][i] = val

        ans = INF
        for j in range(n-1):
            if dp[n-1][j] < INF:
                ans = min(ans, dp[n-1][j] + dist(j, n-1))

        results.append(f"{ans:.3f}")

    print('\n'.join(results))

